purge_demo_account_contract.sql:
-- Run after schema.sql. Fails if a restrictive FK onto a purge target is
-- missing from the routine's supported-reference allowlist, or vice versa.
DO $$
DECLARE actual text[];
DECLARE expected text[] := ARRAY[
    'orders->accounts',
    'invoice_audit->orders'
];
DECLARE owner_name name;
DECLARE security_definer boolean;
DECLARE routine_config text[];
BEGIN
    SELECT array_agg(format('%s->%s', c.conrelid::regclass, c.confrelid::regclass) ORDER BY 1)
      INTO actual
      FROM pg_catalog.pg_constraint c
     WHERE c.contype = 'f' AND c.confdeltype IN ('a', 'r')
       AND c.confrelid IN ('public.accounts'::regclass, 'public.orders'::regclass);
    IF actual IS DISTINCT FROM expected THEN
        RAISE EXCEPTION 'restrictive foreign keys onto purge targets differ: expected %, found %', expected, actual;
    END IF;

    SELECT r.rolname, p.prosecdef, p.proconfig
      INTO owner_name, security_definer, routine_config
      FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_roles r ON r.oid = p.proowner
     WHERE p.oid = 'public.purge_demo_account(text)'::regprocedure;
    IF owner_name <> 'demo_purger' OR NOT security_definer
       OR NOT EXISTS (SELECT 1 FROM unnest(routine_config) cfg WHERE cfg LIKE 'search_path=%') THEN
        RAISE EXCEPTION 'purge function must be SECURITY DEFINER, owned by demo_purger, with pinned search_path';
    END IF;
    IF pg_catalog.pg_has_role('app', 'demo_purger', 'MEMBER') THEN
        RAISE EXCEPTION 'app must not be able to assume demo_purger';
    END IF;
END
$$;

schema.sql:
-- PostgreSQL 18 shop schema.
CREATE ROLE app LOGIN NOSUPERUSER NOINHERIT;
CREATE ROLE demo_purger NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT;

CREATE TABLE accounts (
    id text PRIMARY KEY,
    is_demo boolean NOT NULL
);

CREATE TABLE orders (
    id text PRIMARY KEY,
    account_id text NOT NULL REFERENCES accounts(id),
    state text NOT NULL DEFAULT 'NEW'
);

CREATE TABLE invoice_audit (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id text NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,
    completed_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE FUNCTION guard_invoice_audit() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
    IF current_user <> 'demo_purger' THEN
        RAISE EXCEPTION 'invoice audit records are immutable' USING ERRCODE = '42501';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NULL;
END
$$;

CREATE TRIGGER invoice_audit_no_delete
BEFORE DELETE ON invoice_audit
FOR EACH ROW EXECUTE FUNCTION guard_invoice_audit();

CREATE TRIGGER invoice_audit_no_truncate
BEFORE TRUNCATE ON invoice_audit
FOR EACH STATEMENT EXECUTE FUNCTION guard_invoice_audit();

CREATE FUNCTION reject_invoice_audit_update() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
    RAISE EXCEPTION 'invoice audit records are immutable' USING ERRCODE = '42501';
END
$$;
CREATE TRIGGER invoice_audit_no_update
BEFORE UPDATE ON invoice_audit
FOR EACH ROW EXECUTE FUNCTION reject_invoice_audit_update();

CREATE FUNCTION complete_order(order_id text) RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
DECLARE changed_order text;
BEGIN
    UPDATE public.orders
       SET state = 'DONE'
     WHERE id = complete_order.order_id AND state <> 'DONE'
     RETURNING id INTO changed_order;
    IF FOUND THEN
        INSERT INTO public.invoice_audit(order_id) VALUES (changed_order);
    END IF;
    IF NOT FOUND AND NOT EXISTS (SELECT 1 FROM public.orders WHERE id = complete_order.order_id) THEN
        RAISE EXCEPTION 'order % does not exist', complete_order.order_id USING ERRCODE = 'P0002';
    END IF;
END
$$;

-- This allowlist is checked before the first delete. Add an explicit purge path
-- and update purge_demo_account_contract.sql if the schema gains a reference.
CREATE FUNCTION purge_demo_account(account_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE account_is_demo boolean;
DECLARE unsupported text;
BEGIN
    SELECT is_demo INTO account_is_demo FROM public.accounts WHERE id = purge_demo_account.account_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF NOT account_is_demo THEN
        RAISE EXCEPTION 'account % is not a demo account', purge_demo_account.account_id USING ERRCODE = '42501';
    END IF;

    SELECT format('%I.%I', ns.nspname, rel.relname) INTO unsupported
      FROM pg_catalog.pg_constraint c
      JOIN pg_catalog.pg_class rel ON rel.oid = c.conrelid
      JOIN pg_catalog.pg_namespace ns ON ns.oid = rel.relnamespace
     WHERE c.contype = 'f' AND c.confdeltype IN ('a', 'r')
       AND c.confrelid IN ('public.accounts'::regclass, 'public.orders'::regclass)
       AND NOT ((c.confrelid = 'public.accounts'::regclass AND c.conrelid = 'public.orders'::regclass)
             OR (c.confrelid = 'public.orders'::regclass AND c.conrelid = 'public.invoice_audit'::regclass))
     LIMIT 1;
    IF unsupported IS NOT NULL THEN
        RAISE EXCEPTION 'unsupported relation % prevents demo account reset', unsupported USING ERRCODE = 'P0001';
    END IF;

    DELETE FROM public.invoice_audit a USING public.orders o
     WHERE a.order_id = o.id AND o.account_id = purge_demo_account.account_id;
    DELETE FROM public.orders WHERE orders.account_id = purge_demo_account.account_id;
    DELETE FROM public.accounts WHERE accounts.id = purge_demo_account.account_id;
END
$$;
ALTER FUNCTION purge_demo_account(text) OWNER TO demo_purger;
GRANT SELECT, DELETE ON public.orders, public.invoice_audit TO demo_purger;
GRANT SELECT, UPDATE, DELETE ON public.accounts TO demo_purger;

GRANT SELECT, INSERT, UPDATE ON public.accounts, public.orders TO app;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.invoice_audit TO app;
GRANT USAGE, SELECT ON SEQUENCE public.invoice_audit_id_seq TO app;
REVOKE ALL ON FUNCTION purge_demo_account(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION purge_demo_account(text) TO app;
REVOKE ALL ON FUNCTION complete_order(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION complete_order(text) TO app;
